package reqs

import "testing"

// TestCompletionRuleResidue checks the readings of completion_residue.go.
func TestCompletionRuleResidue(t *testing.T) {
	runComplRuleCases(t, []complRuleCase{
		{"the Faculty's breadth rule unless a course is completed: a constraint over the transcript (ASMAJ0908, shortened)",
			"(6.0 credits)\nAt least 6.0 FAH credits fulfilling the following distribution requirements:\nFirst Year:\nFAH101H1/ FAH102H1\nIn addition, the Faculty of Arts and Science requires Art History Majors who do not complete FAH275H1, FAH338H1, or ARH440H1 to complete at least one 0.5 credit in Arts and Science courses in Breadth Category 5: The Physical and Mathematical Universes.",
			[]string{
				`1 allocation {"type":"credits","amount":6,"designators":["FAH"]}`,
				`2 allocation p1 {"type":"or","items":[{"type":"course","code":"FAH101H1"},{"type":"course","code":"FAH102H1"}]}`,
				`3 constraint p1 scope:transcript {"type":"or","items":[{"type":"course","code":"FAH275H1"},{"type":"course","code":"FAH338H1"},{"type":"course","code":"ARH440H1"},{"type":"credits","amount":0.5,"breadth":[5]}]}`,
			},
			nil},
		{"a course or a breadth credit, then a pool of groups with a floor and a cap (ASMAJ0797, shortened)",
			"(2.0 credits)\nFirst Year:\nCIN105Y1\nSecond, Third and Fourth Year:\nIn addition, CIN230H1 (a Breadth Category 3 course) or 0.5 credit from Breadth Category 5; and at least 0.5 credits from Groups B through C, of which 0.5 credits must be at the 300/400-level, and only a maximum of 0.5 credits can be from Group C: Cross-Listed\n_Group B: Genre and Modes_\nCIN210H1, CIN211H1, CIN310Y1\n_Group C: Cross-Listed_\nCLT355H1, EAS242H1, EAS243H1",
			[]string{
				`1 allocation {"type":"credits","amount":2}`,
				`2 allocation p1 {"type":"course","code":"CIN105Y1"}`,
				`3 allocation p1 {"type":"or","items":[{"type":"course","code":"CIN230H1"},{"type":"credits","amount":0.5,"breadth":[5]}]}`,
				`4 allocation p1 {"type":"credits","amount":0.5,"lists":["Group B","Group C"]}`,
				`5 constraint p4 {"type":"credits","amount":0.5,"levels":[300,400]}`,
				`6 limit p4 {"type":"credits","lists":["Group C"],"max_amount":0.5}`,
				`list: Group B (Group B: Genre and Modes): [{"type":"credits","courses":["CIN210H1","CIN211H1","CIN310Y1"]}]`,
				`list: Group C (Group C: Cross-Listed): [{"type":"credits","courses":["CLT355H1","EAS242H1","EAS243H1"]}]`,
			},
			nil},
		{"courses another item lists and the lists below: a union (ASMIN1231, shortened)",
			"2.0 credits\n1. 1.0 credit from the foundational courses: MST201H1/ MST202H1/ MST222H1\n2. 1.0 credit drawn from the foundational courses list and from the elective courses listed below.\n_Medievalism:_\nMST110H1/ MST211H1/ MST230H1\n_The Arts:_\nMST326H1/ MST358H1/ FAH215H1",
			[]string{
				`1 allocation {"type":"credits","amount":2}`,
				`2 allocation p1 {"type":"credits","amount":1,"courses":["MST201H1","MST202H1","MST222H1"]}`,
				`3 allocation p1 {"type":"credits","amount":1,"lists":["Requirement 2 courses"]}`,
				`list: Medievalism: [{"type":"credits","courses":["MST110H1","MST211H1","MST230H1"]}]`,
				`list: The Arts: [{"type":"credits","courses":["MST326H1","MST358H1","FAH215H1"]}]`,
				`list: Requirement 2 courses: [{"type":"credits","courses":["MST201H1","MST202H1","MST222H1"]},{"type":"credits","lists":["Medievalism","The Arts"]}]`,
			},
			nil},
		{"languages and their courses: a pool per language, a short one its course, the non-language courses as content (ASMAJ1626, shortened)",
			"(2.0 credits)\n1. 1.0 credit from one of the following languages, or 1.0 credit in **non-language** courses related to your chosen language of study, selected in consultation with the Program Coordinator:\n- Finnish: FIN300H1 and FIN340H1\n- French: FSL420H1/ FSL442H1/ FSL443H1\n- Macedonian: SLA209H1\n2. EUR200Y1",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"credits","amount":2},{"type":"text","kind":"content","text":"(2.0 credits)"}]}`,
				`2 allocation p1 {"type":"or","items":[{"type":"and","items":[{"type":"course","code":"FIN300H1"},{"type":"course","code":"FIN340H1"}]},{"type":"credits","amount":1,"courses":["FSL420H1","FSL442H1","FSL443H1"]},{"type":"course","code":"SLA209H1"},{"type":"text","kind":"content","text":"1.0 credit in non-language courses related to your chosen language of study, selected in consultation with the Program Coordinator"}]}`,
				`3 allocation p1 {"type":"course","code":"EUR200Y1"}`,
			},
			nil},
		{"languages by designator, the language as content (ASSPE0385, ASSPE0532, shortened)",
			"(5.0 credits)\n1. 3.0 credits in Hebrew or Yiddish\n2. 2.0 credits in a language relevant to Renaissance Studies – French, Italian, Latin (only 1.0 credit may be at the introductory level)",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"credits","amount":5},{"type":"text","kind":"content","text":"(5.0 credits)"}]}`,
				`2 allocation p1 {"type":"and","items":[{"type":"credits","amount":3,"designators":["MHB","NML","GER"]},{"type":"text","kind":"content","text":"3.0 credits in Hebrew or Yiddish"}]}`,
				`3 allocation p1 {"type":"and","items":[{"type":"credits","amount":2,"designators":["FRE","FSL","ITA","LAT"]},{"type":"text","kind":"content","text":"2.0 credits in a language relevant to Renaissance Studies – French, Italian, Latin (only 1.0 credit may be at the introductory level)"}]}`,
			},
			nil},
		{"the remaining courses from codes or a unit's courses: the total less the most the other items take (ASMIN1163, shortened)",
			"(4.0 credits)\n1. ( GER260Y1/ ( GER261H1 and GER262H1) and GER360H1)/ GER463Y1\n2. GER460H1/ GER462H1\n3. The remaining courses should be taken from: GER361H1, GER367H1, JGJ360H1, GER100Y1, GER150H1, or any course offered by and cross-listed by the Centre for Jewish Studies",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"credits","amount":4},{"type":"text","kind":"other","text":"(4.0 credits)"}]}`,
				`2 allocation p1 {"type":"or","items":[{"type":"and","items":[{"type":"or","items":[{"type":"course","code":"GER260Y1"},{"type":"and","items":[{"type":"course","code":"GER261H1"},{"type":"course","code":"GER262H1"}]}]},{"type":"course","code":"GER360H1"}]},{"type":"course","code":"GER463Y1"}]}`,
				`3 allocation p1 {"type":"or","items":[{"type":"course","code":"GER460H1"},{"type":"course","code":"GER462H1"}]}`,
				`4 allocation p1 {"type":"or","items":[{"type":"credits","amount":2,"courses":["GER361H1","GER367H1","JGJ360H1","GER100Y1","GER150H1"]},{"type":"and","items":[{"type":"credits","amount":2},{"type":"text","kind":"content","text":"any course offered by and cross-listed by the Centre for Jewish Studies"}]}]}`,
			},
			nil},
		{"two groups with a floor each and the rest from either: the pool and the floors as parts (ASSPE0155, shortened)",
			"(3.0 credits)\n1. 3.0 credits from Groups A and B, of which 1.0 credits must be from Group A and 1.0 credits must be from Group B and 1.0 credit from either group\nNote that students may substitute ARH495H1 (Research Practicum) for 0.5 credit of this requirement (assignment to Group A or B to be determined by Undergraduate Coordinator).\n**Group A:** Theoretical and Methods 1: Theoretical\nANT210H1, ANT215H1, NMC466H1\n**Group A:** Theoretical and Methods 5: Osteoarchaeology\nANT334H1/ ANT334Y1, ANT335Y1\n**Group B:** Area Courses and Cultural History 6: Near Eastern Archaeology\nNMC260H1, NMC262H1, NMC466H1",
			[]string{
				`1 allocation {"type":"credits","amount":3}`,
				`2 allocation p1 {"type":"or","items":[{"type":"credits","amount":3,"lists":["Group A","Group B"]},{"type":"and","items":[{"type":"credits","amount":3,"courses":["ANT210H1","ANT215H1","NMC466H1","ANT334H1","ANT334Y1","ANT335Y1","NMC260H1","NMC262H1","ARH495H1"]},{"type":"text","kind":"permission","text":"Note that students may substitute ARH495H1 (Research Practicum) for 0.5 credit of this requirement (assignment to Group A or B to be determined by Undergraduate Coordinator)"}]}]}`,
				`3 constraint p2 {"type":"or","items":[{"type":"and","items":[{"type":"credits","amount":1,"exclude":["NMC466H1"],"lists":["Group A"]},{"type":"credits","amount":1,"exclude":["NMC466H1"],"lists":["Group B"]}]},{"type":"and","items":[{"type":"credits","amount":1,"lists":["Group A"]},{"type":"credits","amount":1,"lists":["Group B"]},{"type":"text","kind":"ambiguity","text":"NMC466H1 is on Group A and Group B: a course counts toward one of them only"}]},{"type":"and","items":[{"type":"credits","amount":1,"courses":["ANT210H1","ANT215H1","ANT334H1","ANT334Y1","ANT335Y1","ARH495H1"]},{"type":"credits","amount":1,"courses":["NMC260H1","NMC262H1","ARH495H1"]},{"type":"text","kind":"permission","text":"Note that students may substitute ARH495H1 (Research Practicum) for 0.5 credit of this requirement (assignment to Group A or B to be determined by Undergraduate Coordinator)"}]}]}`,
				`4 limit p2 {"type":"credits","courses":["ANT334H1","ANT334Y1"],"max_amount":1}`,
				`5 limit p2 {"type":"credits","courses":["ARH495H1"],"max_amount":0.5}`,
				`list: Group A: [{"type":"credits","courses":["ANT210H1","ANT215H1","NMC466H1","ANT334H1","ANT334Y1","ANT335Y1"]}]`,
				`list: Group B (Group B: Area Courses and Cultural History 6: Near Eastern Archaeology): [{"type":"credits","courses":["NMC260H1","NMC262H1","NMC466H1"]}]`,
			},
			nil},
		{"an amount from the core group or from the groups (ASMIN1141, shortened)",
			"(2.5 credits)\n1. 1.0 credit in any area from the Core Group: CAR215H1, CSE241Y1, CSE260H1\n2. 1.5 additional credits in any area from the Core Group, or 1.5 credits from Groups A, B\n**Group A: Gender**\nANT343H1, ANT460H1, CAR317H1\n**Group B: Race, Anti-Racism and Ethnicity**\nAFR150Y1, AFR250Y1",
			[]string{
				`1 allocation {"type":"credits","amount":2.5}`,
				`2 allocation p1 {"type":"credits","amount":1,"courses":["CAR215H1","CSE241Y1","CSE260H1"]}`,
				`3 allocation p1 {"type":"or","items":[{"type":"credits","amount":1.5,"courses":["CAR215H1","CSE241Y1","CSE260H1"]},{"type":"credits","amount":1.5,"lists":["Group A","Group B"]},{"type":"and","items":[{"type":"credits","amount":1.5,"lists":["Requirement 2 courses"]},{"type":"text","kind":"ambiguity","text":"the credits may be drawn from the Core Group and the Groups together"}]}]}`,
				`list: Group A (Group A: Gender): [{"type":"credits","courses":["ANT343H1","ANT460H1","CAR317H1"]}]`,
				`list: Group B (Group B: Race, Anti-Racism and Ethnicity): [{"type":"credits","courses":["AFR150Y1","AFR250Y1"]}]`,
				`list: Requirement 2 courses: [{"type":"credits","courses":["CAR215H1","CSE241Y1","CSE260H1"]},{"type":"credits","lists":["Group A","Group B"]}]`,
			},
			nil},
		{"two consecutive language courses in one of the languages: a pool per language, the sequence as content (ASSPE1525, shortened)",
			"(2.0 credits)\n1. Two consecutive language courses (2.0 credits) in one of: Chinese, Sanskrit, Pali or Tibetan.\n   **Chinese:** EAS100Y1, EAS101Y1, EAS200Y1, EAS201H1, EAS300Y1\n   **Sanskrit:** RLG260H1, RLG263H1, RLG359H1, RLG360H1\n   **Pali:** RLG264H1, RLG265H1, and an additional 1.0 credit in consultation with the Department for the Study of Religion\n   **Tibetan:** RLG261H1, RLG262H1, RLG370Y1/ ( RLG377H1, RLG378H1)",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"credits","amount":2},{"type":"text","kind":"content","text":"(2.0 credits)"}]}`,
				`2 allocation p1 {"type":"and","items":[{"type":"or","items":[{"type":"credits","amount":2,"courses":["EAS100Y1","EAS101Y1","EAS200Y1","EAS201H1","EAS300Y1"]},{"type":"and","items":[{"type":"course","code":"RLG260H1"},{"type":"course","code":"RLG263H1"},{"type":"course","code":"RLG359H1"},{"type":"course","code":"RLG360H1"}]},{"type":"and","items":[{"type":"course","code":"RLG264H1"},{"type":"course","code":"RLG265H1"},{"type":"credits","amount":1},{"type":"text","kind":"permission","text":"Pali: an additional 1.0 credit in consultation with the Department for the Study of Religion"}]},{"type":"and","items":[{"type":"course","code":"RLG261H1"},{"type":"course","code":"RLG262H1"},{"type":"or","items":[{"type":"course","code":"RLG370Y1"},{"type":"and","items":[{"type":"course","code":"RLG377H1"},{"type":"course","code":"RLG378H1"}]}]}]}]},{"type":"text","kind":"content","text":"Two consecutive language courses"}]}`,
			},
			nil},
		{"Department for the Study of Religion courses: the designators, with an exclusion, in an area of focus, and as an item's floor (ASSPE0151, ASMAJ1525, shortened)",
			"(5.0 credits)\n1. 0.5 credit in any other 200-level Department for the Study of Religion courses (excluding the following language courses: MHB255H1, RLG260H1).\n2. 0.5 credit at the 400-level in your area of focus selected from Department for the Study of Religion courses.\n3. 4.0 credits chosen from the following list; at least 3.0 credits of which must be Department for the Study of Religion courses (RLG, JAR, JCR, JNR, JPR, JRC, JRN, or JSR designators).\n   **Second year courses:** RLG205H1, FAH260H1, EAS209H1, HIS280Y1, HIS282Y1, HIS283Y1, PHL237H1.\n   **Third year courses:** RLG311H1, RLG361H1, RLG363H1, RLG366H1, EAS338H1, JNR301H1, PHL337H1.\nNotes:\n- Courses with RLG, JAR, JCR, JNR, JPR, JRC, JRN, and JSR designators count as Department for the Study of Religion courses.",
			[]string{
				`1 allocation {"type":"or","items":[{"type":"credits","amount":5},{"type":"text","kind":"content","text":"(5.0 credits)"}]}`,
				`2 allocation p1 {"type":"credits","amount":0.5,"designators":["RLG","JAR","JCR","JNR","JPR","JRC","JRN","JSR"],"levels":[200],"exclude":["MHB255H1","RLG260H1"]}`,
				`3 allocation p1 {"type":"and","items":[{"type":"credits","amount":0.5,"designators":["RLG","JAR","JCR","JNR","JPR","JRC","JRN","JSR"],"levels":[400]},{"type":"text","kind":"content","text":"in your area of focus"}]}`,
				`4 allocation p1 {"type":"credits","amount":4,"courses":["RLG205H1","FAH260H1","EAS209H1","HIS280Y1","HIS282Y1","HIS283Y1","PHL237H1","RLG311H1","RLG361H1","RLG363H1","RLG366H1","EAS338H1","JNR301H1","PHL337H1"]}`,
				`5 constraint p4 {"type":"credits","amount":3,"designators":["RLG","JAR","JCR","JNR","JPR","JRC","JRN","JSR"]}`,
			},
			nil},
	})
}
